    let cost_root = include_str!("../../src/workspace_graph/expected_projection/cost.rs");
    assert!(cost_root.contains(
        "#[cfg(test)]\n#[path = \"uncached_absence_tests.rs\"]\nmod uncached_absence_tests;"
