            "sha256:b14145b8e6975212415b282b2f67e5e38d1e43bea2c8a5f689c003a9883a21ac",
            "sha256:6d503a367d03d11fa4cb37e50f579bc16f0e22c3469f47dbbbd05647c93f1eca",
        ]
    );

    std::thread::scope(|scope| {
        let context_task = scope.spawn(|| {
            workspace_analysis::context(
                &fixture.root,
                "public.app",
                WorkspaceAnalysisTargetKind::Declaration,
                "public.main",
                WorkspaceContextOptions::default(),
