        "fn dependency_depths<'a>(",
        "fn synthetic_program(",
        "fn collect_expected_edges(",
        "fn verify_resolved_call_edges(",
    ] {
        assert_eq!(
            root.matches(moved).count() + projection.matches(moved).count(),
